          "topic": "Фізична база: що вже знаємо з теми «Електрика»",
          "questionHtml": "<p>Дві лампи підключено до однієї пари вузлів. Який зв’язок між напрямком струму й полюсами джерела прийнято для зовнішньої частини кола?</p>",
