          "correctKey": "Г",
          "answerText": "Установка використовує гарячий розплав із розчиненим оксидом алюмінію. На від’ємному графітовому дні йони алюмінію відновлюються; отриманий рідкий метал опускається на дно. Кисневі йони віддають електрони біля вугільних анодів, і газ реагує з їхнім вуглецем.",
          "optionSource": "prepared-v21-test",
