          "correctKey": "В",
          "answerText": "На довгій лінії втрати й обмеження смуги стають визначальними.",
          "optionSource": "prepared-v21-test",
          "explanationSource": "prepared-v21-test",
          "sourceFile": "data/flashcards/grade-9/sources/v21/physics-9-v21/Фізика_9_Бар’яхтар_2026_пар_25_ТЕСТИ_20.md"
