          "answerText": "Авторська відповідь — маска. У §33 пояснено тривалість внутрішнього опромінення радіонуклідами, що потрапили в організм; у §31 зазначено малу зовнішню проникність α-частинок. Тест перевіряє пояснення навчальної задачі, а не вибір засобу для конкретної аварійної ситуації.",
